import java.util.Scanner;

public class Main {
    static long total_moves = 0;

    static int countDigits(long num) {
        int count = 0;
        while (num != 0) {
            num /= 10;
            count++;
        }
        return count;
    }

    static long getThreshold(long num) {
        int digits = countDigits(num);
        long base = 0;
        long factor = 1;
        for (int i = 0; i < digits; i++) {
            base += factor;
            factor *= 10;
        }
        if (base <= num) return base;
        return (base - 1) / 10;
    }

    static long recursiveSolve(long n) {
        if (n <= 6) return n;
        if (n <= 11) return 13 - n;
        long base_num = getThreshold(n);
        long boundary = base_num * 10 + 1;
        if (n % base_num == 0) {
            long quotient = n / base_num;
            if (n <= boundary / 2 + base_num) {
                return countDigits(base_num) * quotient;
            } else {
                long diff = recursiveSolve(boundary - n);
                return countDigits(boundary) + diff;
            }
        } else {
            long lower_bound = (n / base_num) * base_num;
            long upper_bound = (n / base_num + 1) * base_num;
            long res = recursiveSolve(lower_bound) + recursiveSolve(n - lower_bound);
            if (n > boundary / 2) {
                long temp1 = recursiveSolve(lower_bound) + recursiveSolve(n - lower_bound);
                long temp2 = countDigits(boundary) + recursiveSolve(boundary - n);
                res = Math.min(temp1, temp2);
            }
            return res;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long n = scanner.nextLong();
        System.out.println(recursiveSolve(n));
        scanner.close();
    }
}
